import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { Archive, Check, ChevronDown, ClipboardList, Loader2, LogOut, Menu, Package, Pencil, Phone, RefreshCw, Search, Settings, SlidersHorizontal, Trash2, Truck, X } from 'lucide-react';

type OrderStatus = 'abandoned' | 'complete' | 'confirmed' | 'not_responding' | 'cancelled' | 'shipped' | 'delivered' | 'returned' | 'trashed';
type ProviderProfile = { id: string; name: string; provider: string; token?: string; tokenConfigured?: boolean; deliveryFees?: Record<string, { home: number; stopDesk: number }> };
type StockProduct = { id: number; name: string; sku: string | null; quantity: number; active: boolean };
type Order = {
  id: number; lead_id: string; status: OrderStatus; status_before_trash: OrderStatus | null; trashed_at: string | null; campaign: string; price: number; delivery_fee: number; delivery_type: string | null;
  phone: string; full_name: string | null; wilaya: string | null; commune: string | null; ecotrack_tracking: string | null; ecotrack_status: string | null; gift_booklet: boolean; shipping_provider_id: string | null; shipping_provider_name: string | null; stock_product_id: number | null; stock_product_name: string | null; ship_from_stock: boolean; created_at: string; updated_at: string;
};

const statusLabels: Record<OrderStatus | 'all', string> = {
  all: 'الكل', abandoned: 'غير مكتملة', complete: 'مكتملة', confirmed: 'مؤكدة', not_responding: 'لا يستجيب', cancelled: 'ملغاة', shipped: 'مرفوعة إلى EcoTrack', delivered: 'تم التسليم', returned: 'مرتجعة', trashed: 'سلة المهملات',
};
const formatDate = (value: string) => new Intl.DateTimeFormat('ar-DZ', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value));
const ecoStatusLabel = (value: string | null) => ({ created: 'تم إنشاء الشحنة', delivered: 'تم التسليم', returned: 'مرتجعة', cancelled: 'ملغاة في EcoTrack', pending: 'قيد الانتظار' }[value || ''] || value || 'غير مرفوعة');
const WILAYAS = ['01 - أدرار','02 - الشلف','03 - الأغواط','04 - أم البواقي','05 - باتنة','06 - بجاية','07 - بسكرة','08 - بشار','09 - البليدة','10 - البويرة','11 - تمنراست','12 - تبسة','13 - تلمسان','14 - تيارت','15 - تيزي وزو','16 - الجزائر','17 - الجلفة','18 - جيجل','19 - سطيف','20 - سعيدة','21 - سكيكدة','22 - سيدي بلعباس','23 - عنابة','24 - قالمة','25 - قسنطينة','26 - المدية','27 - مستغانم','28 - المسيلة','29 - معسكر','30 - ورقلة','31 - وهران','32 - البيض','33 - إليزي','34 - برج بوعريريج','35 - بومرداس','36 - الطارف','37 - تندوف','38 - تيسمسيلت','39 - الوادي','40 - خنشلة','41 - سوق أهراس','42 - تيبازة','43 - ميلة','44 - عين الدفلى','45 - النعامة','46 - عين تموشنت','47 - غرداية','48 - غليزان','49 - المغير','50 - المنيعة','51 - أولاد جلال','52 - بني عباس','53 - برج باجي مختار','54 - تيميمون','55 - تقرت','56 - جانت','57 - عين صالح','58 - عين قزام'];

export default function Dashboard() {
  const [password, setPassword] = useState(() => sessionStorage.getItem('atlasio:dashboard-password') || '');
  const [passwordInput, setPasswordInput] = useState('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [status, setStatus] = useState<OrderStatus | 'all'>('all');
  const [section, setSection] = useState<'orders' | 'incomplete' | 'trash'>('orders');
  const [showAllOrders, setShowAllOrders] = useState(false);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [provider, setProvider] = useState('navexdelivery');
  const [token, setToken] = useState('');
  const [tokenConfigured, setTokenConfigured] = useState(false);
  const [providers, setProviders] = useState<ProviderProfile[]>([]);
  const [activeProviderId, setActiveProviderId] = useState('');
  const [providerNameDraft, setProviderNameDraft] = useState('');
  const [editingProviderId, setEditingProviderId] = useState('');
  const [stockProducts, setStockProducts] = useState<StockProduct[]>([]);
  const [selectedProviderId, setSelectedProviderId] = useState('');
  const [selectedStockProductId, setSelectedStockProductId] = useState('');
  const [shipFromStock, setShipFromStock] = useState(true);
  const [feeText, setFeeText] = useState('{}');
  const [savingSettings, setSavingSettings] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [editing, setEditing] = useState<Order | null>(null);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activeOrderId, setActiveOrderId] = useState<number | null>(null);
  const touchStartX = useRef<number | null>(null);
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [bulkBusy, setBulkBusy] = useState(false);
  const goToSection = (nextSection: 'orders' | 'incomplete' | 'trash') => { setSection(nextSection); setStatus('all'); setShowAllOrders(false); setSelectedIds([]); setDrawerOpen(false); };
  const [editForm, setEditForm] = useState({ fullName: '', phone: '', wilaya: '', commune: '', price: '', deliveryFee: '' });
  const [editCommunes, setEditCommunes] = useState<Array<{ name: string; hasStopDesk: boolean }>>([]);
  const startEditing = (order: Order) => {
    setEditing(order); setEditForm({ fullName: order.full_name || '', phone: order.phone, wilaya: order.wilaya || '', commune: order.commune || '', price: String(order.price), deliveryFee: String(order.delivery_fee || 0) }); setEditCommunes([]);
    void fetch(`/api/orders?resource=communes&wilaya=${encodeURIComponent(order.wilaya || '')}`).then((response) => response.ok ? response.json() : Promise.reject(new Error('communes'))).then((data: { communes?: Array<{ name: string; hasStopDesk: boolean }> }) => setEditCommunes(data.communes || [])).catch(() => setEditCommunes([]));
  };

  const authHeaders = (nextPassword = password) => ({ 'X-Dashboard-Password': nextPassword });

  const loadOrders = async (nextPassword = password) => {
    if (!nextPassword) return;
    setLoading(true); setError('');
    try {
      const response = await fetch('/api/orders', { headers: authHeaders(nextPassword) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(response.status === 401 ? 'كلمة المرور غير صحيحة' : (data.error || 'تعذر تحميل الطلبات'));
      setOrders(data.orders || []); sessionStorage.setItem('atlasio:dashboard-password', nextPassword); setPassword(nextPassword);
      await loadSettings(nextPassword);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر تحميل الطلبات'); }
    finally { setLoading(false); }
  };

  const loadSettings = async (nextPassword = password) => {
    if (!nextPassword) return;
    const response = await fetch('/api/orders?resource=settings', { headers: authHeaders(nextPassword) });
    if (!response.ok) return;
    const data = await response.json(); setProvider(data.provider || 'navexdelivery'); setTokenConfigured(Boolean(data.tokenConfigured)); setFeeText(JSON.stringify(data.deliveryFees || {}, null, 2)); setProviders(data.providers || []); setActiveProviderId(data.activeProviderId || data.providers?.[0]?.id || ''); setSelectedProviderId(data.activeProviderId || data.providers?.[0]?.id || ''); const activeProvider = (data.providers || []).find((item: ProviderProfile) => item.id === (data.activeProviderId || '')) || (data.providers || [])[0]; setProviderNameDraft(activeProvider?.name || ''); setEditingProviderId(activeProvider?.id || '');
    const stockProviderId = data.activeProviderId || data.providers?.[0]?.id || '';
    const stockResponse = await fetch(`/api/orders?resource=stock&providerId=${encodeURIComponent(stockProviderId)}`, { headers: authHeaders(nextPassword) });
    const stockData = await stockResponse.json().catch(() => ({}));
    if (!stockResponse.ok) { setStockProducts([]); setSelectedStockProductId(''); setError(stockData.error || 'تعذر جلب منتجات المخزون من الشركة النشطة'); return; }
    const nextProducts = stockData.products || [];
    setStockProducts(nextProducts);
    setSelectedStockProductId(nextProducts[0] ? String(nextProducts[0].id) : '');
    setShipFromStock((current) => (nextProducts.length === 0 ? true : current));
  };

  useEffect(() => { if (password) void loadOrders(); // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const updateStatus = async (id: number, nextStatus: OrderStatus) => {
    setError(''); setLoading(true);
    try {
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({ id, status: nextStatus }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر تحديث حالة الطلب');
      setOrders((current) => current.map((order) => order.id === id ? (data.order || { ...order, status: nextStatus }) : order));
      setSelectedIds((current) => current.filter((item) => item !== id));
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر تحديث حالة الطلب'); }
    finally { setLoading(false); }
  };

  const saveProviderProfile = async () => {
    const name = providerNameDraft.trim(); const providerCode = provider.trim().toLowerCase(); const providerToken = token.trim();
    if (!name || !providerCode || (!providerToken && !editingProviderId)) { setError('أدخل اسم الشركة وProvider والتوكن'); return; }
    setSavingSettings(true); setError('');
    try {
      const id = editingProviderId || `provider-${Date.now()}`;
      const nextProviders = [...providers.filter((item) => item.id !== id), { id, name, provider: providerCode, token: providerToken }];
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({ resource: 'settings', providers: nextProviders, activeProviderId: activeProviderId || id }) });
      const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'تعذر حفظ شركة التوصيل');
      setProviders(data.providers || []); setActiveProviderId(data.activeProviderId || id); setSelectedProviderId(data.activeProviderId || id); setEditingProviderId(id); setToken(''); setTokenConfigured(true); await refreshStock(data.activeProviderId || id);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر حفظ شركة التوصيل'); }
    finally { setSavingSettings(false); }
  };

  const refreshStock = async (providerId: string) => {
    if (!providerId) { setStockProducts([]); setSelectedStockProductId(''); setError('اختر شركة توصيل نشطة أولاً'); return; }
    try {
      const response = await fetch(`/api/orders?resource=stock&providerId=${encodeURIComponent(providerId)}`, { headers: authHeaders() });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر جلب منتجات المخزون من الشركة');
      const nextProducts = data.products || [];
      setStockProducts(nextProducts); setSelectedStockProductId(nextProducts[0] ? String(nextProducts[0].id) : ''); setShipFromStock((current) => (nextProducts.length === 0 ? true : current));
      if (nextProducts.length === 0) setError('لم تُرجع الشركة كتالوج منتجات؛ يمكن استخدام الشحن من stock مباشرة، أو أضف منتجاً محلياً إذا أردت تتبع الكمية.');
      else setError('');
    } catch (requestError) { setStockProducts([]); setSelectedStockProductId(''); setShipFromStock(true); setError(requestError instanceof Error ? requestError.message : 'تعذر جلب كتالوج منتجات الشركة؛ يمكنك متابعة الشحن من stock مباشرة'); }
  };

  const startNewProvider = () => { setEditingProviderId(''); setProviderNameDraft(''); setProvider(''); setToken(''); setTokenConfigured(false); setStockProducts([]); setSelectedStockProductId(''); setShipFromStock(false); };

  const selectProviderForEdit = (item: ProviderProfile) => { setEditingProviderId(item.id); setProviderNameDraft(item.name); setProvider(item.provider); setToken(''); setActiveProviderId(item.id); setSelectedProviderId(item.id); setTokenConfigured(Boolean(item.tokenConfigured)); void refreshStock(item.id); };

  const saveSettings = async (event: FormEvent) => {
    event.preventDefault(); setSavingSettings(true); setError('');
    try {
      let deliveryFees: unknown = {};
      try { deliveryFees = JSON.parse(feeText || '{}'); } catch { throw new Error('صيغة أسعار التوصيل غير صحيحة؛ استخدم JSON صالحاً'); }
      const providerProfiles = providers.map((item) => ({ id: item.id, name: item.name, provider: item.provider, token: item.id === editingProviderId ? token : '' }));
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({ resource: 'settings', providers: providerProfiles, activeProviderId, provider, token, deliveryFees }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر حفظ الإعدادات');
      setProvider(data.provider || provider); setToken(''); setTokenConfigured(Boolean(data.tokenConfigured)); setFeeText(JSON.stringify(data.deliveryFees || {}, null, 2)); setProviders(data.providers || []); setActiveProviderId(data.activeProviderId || activeProviderId); setSelectedProviderId(data.activeProviderId || activeProviderId);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر حفظ الإعدادات'); }
    finally { setSavingSettings(false); }
  };

  const saveEdit = async (event: FormEvent) => {
    event.preventDefault();
    if (!editing) return;
    setLoading(true); setError('');
    try {
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'edit', id: editing.id, ...editForm, price: Number(editForm.price), deliveryFee: Number(editForm.deliveryFee) }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر تعديل الطلب');
      setOrders((current) => current.map((order) => order.id === editing.id ? data.order : order));
      setEditing(null);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر تعديل الطلب'); }
    finally { setLoading(false); }
  };

  const runAction = async (id: number, action: 'ship' | 'unship' | 'trash' | 'restore', shippingModeOverride?: 'stock' | 'without_stock') => {
    setLoading(true); setError('');
    try {
      const shippingMode = action === 'ship' ? (shippingModeOverride || (shipFromStock ? 'stock' : 'without_stock')) : undefined;
      const shouldUseStock = shippingMode === 'stock';
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({
        id,
        action,
        providerId: action === 'ship' ? selectedProviderId : undefined,
        shippingMode,
        stockProductId: action === 'ship' && shouldUseStock ? Number(selectedStockProductId) : undefined,
      }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر تنفيذ العملية');
      setOrders((current) => current.map((order) => order.id === id ? data.order : order));
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر تنفيذ العملية'); }
    finally { setLoading(false); }
  };

  const shipAll = async () => {
    setLoading(true); setError('');
    try {
      const shouldUseStock = shipFromStock && Boolean(selectedStockProductId);
      const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify({
        action: 'shipAll',
        providerId: selectedProviderId,
        shippingMode: shouldUseStock ? 'stock' : 'without_stock',
        stockProductId: shouldUseStock ? Number(selectedStockProductId) : undefined,
      }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذر شحن الطلبات');
      await loadOrders();
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر شحن الطلبات'); }
    finally { setLoading(false); }
  };

  const syncStatuses = async () => {
    setSyncing(true); setError('');
    try {
      const response = await fetch('/api/orders?resource=sync', { headers: authHeaders() });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || 'تعذرت مزامنة EcoTrack');
      await loadOrders();
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذرت مزامنة EcoTrack'); }
    finally { setSyncing(false); }
  };

  const visibleOrders = useMemo(() => orders.filter((order) => {
    const inSection = section === 'trash' ? order.status === 'trashed' : section === 'incomplete' ? ['abandoned', 'not_responding'].includes(order.status) : order.status !== 'trashed' && (showAllOrders || ['confirmed', 'cancelled', 'shipped'].includes(order.status));
    const matchesStatus = status === 'all' || order.status === status;
    const normalizedQuery = query.trim().toLowerCase();
    const haystack = [order.lead_id, order.phone, order.full_name, order.wilaya, order.commune, order.campaign, order.ecotrack_tracking].filter(Boolean).join(' ').toLowerCase();
    return inSection && matchesStatus && (!normalizedQuery || haystack.includes(normalizedQuery));
  }), [orders, query, section, showAllOrders, status]);
  const counts = orders.reduce<Record<string, number>>((result, order) => { result[order.status] = (result[order.status] || 0) + 1; return result; }, {});
  const sectionTitle = section === 'orders' ? 'الطلبات' : section === 'incomplete' ? 'غير مكتملة' : 'سلة المهملات';
  const sectionDescription = section === 'orders' ? 'الطلبات الجاهزة للمتابعة والشحن' : section === 'incomplete' ? 'طلبات تحتاج بيانات أو متابعة قبل اعتمادها' : 'الطلبات المحذوفة مؤقتاً ويمكن استرجاعها';

  const activeOrder = orders.find((order) => order.id === activeOrderId) || null;
  const confirmedCount = counts.confirmed || 0;
  const shippedCount = counts.shipped || 0;
  const deliveredCount = counts.delivered || 0;
  const statusTone = (value: OrderStatus) => value === 'confirmed' ? 'bg-emerald-50 text-emerald-700 ring-emerald-100' : value === 'abandoned' || value === 'not_responding' ? 'bg-amber-50 text-amber-700 ring-amber-100' : value === 'cancelled' || value === 'returned' || value === 'trashed' ? 'bg-rose-50 text-rose-700 ring-rose-100' : value === 'delivered' ? 'bg-violet-50 text-violet-700 ring-violet-100' : 'bg-sky-50 text-sky-700 ring-sky-100';
  const ecoTone = (order: Order) => order.ecotrack_tracking ? (order.status === 'delivered' ? 'bg-violet-50 text-violet-700 ring-violet-100' : order.status === 'returned' ? 'bg-rose-50 text-rose-700 ring-rose-100' : 'bg-blue-50 text-blue-700 ring-blue-100') : 'bg-slate-100 text-slate-500 ring-slate-200';
  const openOrder = (order: Order) => { setActiveOrderId(order.id); setExpandedId(order.id); };
  const closeOrder = () => { setActiveOrderId(null); setExpandedId(null); setEditing(null); };
  const visibleIds = visibleOrders.map((order) => order.id);
  const allVisibleSelected = visibleIds.length > 0 && visibleIds.every((id) => selectedIds.includes(id));
  const toggleSelected = (id: number) => setSelectedIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const toggleSelectAll = () => setSelectedIds((current) => allVisibleSelected ? current.filter((id) => !visibleIds.includes(id)) : [...new Set([...current, ...visibleIds])]);
  const bulkUpdate = async (nextStatus: OrderStatus | null, action: 'trash' | 'restore' | null = null) => {
    if (!selectedIds.length) return;
    setBulkBusy(true); setError('');
    try {
      const results = await Promise.all(selectedIds.map(async (id) => {
        const body = action ? { id, action } : { id, status: nextStatus };
        const response = await fetch('/api/orders', { method: 'PATCH', headers: { ...authHeaders(), 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.error || 'تعذر تنفيذ العملية الجماعية');
        return { id, order: data.order };
      }));
      setOrders((current) => current.map((order) => { const result = results.find((item) => item.id === order.id); return result?.order || order; }));
      setSelectedIds([]); setActiveOrderId(null); setExpandedId(null);
    } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'تعذر تنفيذ العملية الجماعية'); }
    finally { setBulkBusy(false); }
  };

  if (!password) return (
    <main className="min-h-screen bg-[#f4f6f5] px-4 py-16" dir="rtl">
      <div className="mx-auto max-w-md rounded-[28px] border border-white bg-white p-8 shadow-[0_24px_80px_-35px_rgba(15,23,42,.25)]">
        <div className="mb-7 text-center"><div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-emerald-500 text-white shadow-lg shadow-emerald-500/20"><Package className="h-7 w-7" /></div><h1 className="text-2xl font-black text-slate-950">لوحة الطلبات</h1><p className="mt-2 text-sm text-slate-500">أدخل كلمة المرور لإدارة طلبات Atlasio.</p></div>
        <form onSubmit={(event) => { event.preventDefault(); void loadOrders(passwordInput); }} className="space-y-4"><input type="password" value={passwordInput} onChange={(event) => setPasswordInput(event.target.value)} placeholder="كلمة مرور اللوحة" className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3.5 text-right outline-none transition focus:border-emerald-500 focus:bg-white focus:ring-4 focus:ring-emerald-500/10" autoFocus /><button type="submit" disabled={loading || !passwordInput} className="flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 px-4 py-3.5 font-bold text-white transition active:scale-[.98] hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50">{loading && <Loader2 className="h-5 w-5 animate-spin" />} دخول</button></form>
        {error && <p className="mt-4 text-center text-sm font-semibold text-rose-600">{error}</p>}
      </div>
    </main>
  );

  return (
    <main className="admin-dashboard min-h-screen bg-[#f4f6f5] text-slate-950" dir="rtl" onTouchStart={(event) => { touchStartX.current = event.touches[0]?.clientX ?? null; }} onTouchEnd={(event) => { const start = touchStartX.current; const end = event.changedTouches[0]?.clientX; if (start !== null && end !== undefined && start - end > 70) setDrawerOpen(true); if (start !== null && end !== undefined && end - start > 70) setDrawerOpen(false); touchStartX.current = null; }}>
      <div className="mx-auto flex min-h-screen max-w-[1500px]">
        <aside className="hidden w-[238px] shrink-0 flex-col bg-[#0d1a17] p-5 text-white lg:flex"><div className="mb-10 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-emerald-400 font-black text-[#0d1a17]">A</div><div><p className="text-lg font-black tracking-tight">Atlasio</p><p className="text-[10px] text-emerald-200/60">OPERATIONS</p></div></div><nav className="space-y-2 text-sm font-semibold"><button type="button" onClick={() => goToSection('orders')} className={`flex w-full items-center gap-3 rounded-2xl px-3 py-3 transition ${section === 'orders' ? 'bg-white/10 text-emerald-300' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}><ClipboardList className="h-4 w-4" /> الطلبات <span className="mr-auto rounded-full bg-white/10 px-2 py-0.5 text-[10px]">{counts.confirmed || 0}</span></button><button type="button" onClick={() => goToSection('incomplete')} className={`flex w-full items-center gap-3 rounded-2xl px-3 py-3 transition ${section === 'incomplete' ? 'bg-white/10 text-amber-300' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}><Package className="h-4 w-4" /> غير مكتملة <span className="mr-auto rounded-full bg-white/10 px-2 py-0.5 text-[10px]">{(counts.abandoned || 0) + (counts.not_responding || 0)}</span></button><button type="button" onClick={() => goToSection('trash')} className={`flex w-full items-center gap-3 rounded-2xl px-3 py-3 transition ${section === 'trash' ? 'bg-white/10 text-rose-300' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}><Archive className="h-4 w-4" /> سلة المهملات <span className="mr-auto rounded-full bg-white/10 px-2 py-0.5 text-[10px]">{counts.trashed || 0}</span></button><button type="button" onClick={() => void syncStatuses()} className="flex w-full items-center gap-3 rounded-2xl px-3 py-3 text-slate-400 transition hover:bg-white/5 hover:text-white"><RefreshCw className="h-4 w-4" /> مزامنة EcoTrack</button><button type="button" onClick={() => { setSettingsOpen(true); setDrawerOpen(false); }} className="flex w-full items-center gap-3 rounded-2xl px-3 py-3 text-slate-400 transition hover:bg-white/5 hover:text-white"><Settings className="h-4 w-4" /> الإعدادات</button></nav><div className="mt-auto rounded-2xl border border-white/10 bg-white/5 p-3 text-xs"><p className="font-bold text-emerald-300">EcoTrack</p><p className="mt-1 text-slate-400">{tokenConfigured ? 'متصل وجاهز للشحن' : 'يحتاج إعداد التوكن'}</p></div></aside>
        <section className="min-w-0 flex-1 px-4 py-4 sm:px-6 lg:px-10 lg:py-8">
          <header className="mb-5 flex items-center justify-between"><div className="flex items-center gap-3"><button type="button" onClick={() => setDrawerOpen(true)} className="flex h-11 w-11 items-center justify-center rounded-2xl bg-white text-slate-700 shadow-sm ring-1 ring-slate-200 lg:hidden" aria-label="فتح القائمة"><Menu className="h-5 w-5" /></button><div><p className="text-xs font-bold uppercase tracking-[.22em] text-emerald-600">ATLASIO / {sectionTitle}</p><h1 className="mt-1 text-2xl font-black tracking-tight sm:text-3xl">{sectionTitle}</h1></div></div><div className="flex items-center gap-2"><button type="button" onClick={() => void loadOrders()} className="flex h-11 items-center gap-2 rounded-2xl bg-white px-3 text-sm font-bold text-slate-700 shadow-sm ring-1 ring-slate-200 transition active:scale-95"><RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /><span className="hidden sm:inline">تحديث</span></button><button type="button" onClick={() => setDrawerOpen(true)} className="hidden h-11 items-center gap-2 rounded-2xl bg-slate-950 px-4 text-sm font-bold text-white transition active:scale-95 sm:flex lg:hidden"><SlidersHorizontal className="h-4 w-4" /> الأدوات</button></div></header>
          <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-slate-500">{sectionDescription}</p><p className="mt-1 text-sm font-semibold text-slate-400">عرض {visibleOrders.length} من {orders.length} طلب</p></div><button type="button" onClick={() => setDrawerOpen(true)} className="hidden items-center gap-2 rounded-2xl bg-emerald-500 px-4 py-3 text-sm font-black text-white shadow-lg shadow-emerald-500/20 transition active:scale-95 hover:bg-emerald-600 sm:flex"><Truck className="h-4 w-4" /> شحن المؤكدين</button></div>
          <div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><div className="rounded-[22px] bg-white p-4 shadow-sm ring-1 ring-slate-200/70"><p className="text-xs font-bold text-slate-400">في هذا القسم</p><p className="mt-2 text-2xl font-black">{section === 'orders' ? (showAllOrders ? orders.filter((order) => order.status !== 'trashed').length : (counts.confirmed || 0) + (counts.cancelled || 0) + (counts.shipped || 0)) : visibleOrders.length}</p></div><div className="rounded-[22px] bg-emerald-50 p-4 ring-1 ring-emerald-100"><p className="text-xs font-bold text-emerald-700">مؤكدة</p><p className="mt-2 text-2xl font-black text-emerald-800">{confirmedCount}</p></div><div className="rounded-[22px] bg-blue-50 p-4 ring-1 ring-blue-100"><p className="text-xs font-bold text-blue-700">مرفوعة</p><p className="mt-2 text-2xl font-black text-blue-800">{shippedCount}</p></div><div className="rounded-[22px] bg-violet-50 p-4 ring-1 ring-violet-100"><p className="text-xs font-bold text-violet-700">تم التسليم</p><p className="mt-2 text-2xl font-black text-violet-800">{deliveredCount}</p></div></div>
          <section className="mb-4 flex flex-wrap items-center gap-2 rounded-[22px] bg-white p-2 shadow-sm ring-1 ring-slate-200/70">{section === 'orders' && <div className="flex min-w-0 flex-1 gap-1 overflow-x-auto">{(['all', 'confirmed', 'cancelled', 'shipped'] as const).map((item) => <button key={item} type="button" onClick={() => setStatus(item)} className={`flex shrink-0 items-center gap-2 rounded-2xl px-3.5 py-2.5 text-xs font-bold transition active:scale-95 ${status === item ? 'bg-slate-950 text-white shadow-sm' : 'text-slate-500 hover:bg-slate-100'}`}>{item === 'all' ? 'الرئيسية' : statusLabels[item]} <span className={`rounded-full px-1.5 py-0.5 text-[10px] ${status === item ? 'bg-white/15 text-white' : 'bg-slate-100 text-slate-500'}`}>{item === 'all' ? (showAllOrders ? orders.filter((order) => order.status !== 'trashed').length : (counts.confirmed || 0) + (counts.cancelled || 0) + (counts.shipped || 0)) : counts[item] || 0}</span></button>)}</div>}{section === 'orders' && <button type="button" onClick={() => { setShowAllOrders((current) => !current); setStatus('all'); }} className={`rounded-2xl px-3.5 py-2.5 text-xs font-black transition ${showAllOrders ? 'bg-emerald-500 text-white' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'}`}>{showAllOrders ? 'الطلبات الأساسية' : 'عرض كل الطلبات'}</button>}{section === 'trash' && <p className="px-3 py-2 text-xs font-bold text-rose-700">المحذوفات مؤقتاً — يمكنك استرجاعها من تفاصيل الطلب</p>}{section === 'incomplete' && <p className="px-3 py-2 text-xs font-bold text-amber-700">أكمل البيانات أو انقل الطلب للسلة عند الحاجة</p>}</section>
          <section className="mb-5 flex items-center gap-2 rounded-[22px] bg-white p-2 shadow-sm ring-1 ring-slate-200/70"><div className="relative min-w-0 flex-1"><Search className="absolute right-3 top-3 h-5 w-5 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ابحث بالاسم، الهاتف، الولاية أو التتبع" className="w-full rounded-2xl bg-slate-50 py-3 pl-4 pr-10 text-sm outline-none transition placeholder:text-slate-400 focus:bg-white focus:ring-4 focus:ring-emerald-500/10" /></div><button type="button" onClick={() => setDrawerOpen(true)} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-slate-100 text-slate-600" aria-label="الفلاتر"><SlidersHorizontal className="h-5 w-5" /></button></section>
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-[22px] bg-white p-3 shadow-sm ring-1 ring-slate-200/70"><div className="flex items-center gap-3"><button type="button" onClick={toggleSelectAll} className={`flex h-9 w-9 items-center justify-center rounded-xl border transition ${allVisibleSelected ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300 bg-white text-transparent hover:border-emerald-400'}`} aria-label="تحديد الكل">{allVisibleSelected && <Check className="h-4 w-4" />}</button><div><p className="text-sm font-black text-slate-800">{selectedIds.length ? `تم تحديد ${selectedIds.length} طلب` : 'تحديد الطلبات'}</p><p className="text-[11px] font-semibold text-slate-400">{selectedIds.length ? 'اختر إجراءً يطبق على المحدد' : 'يمكنك تنفيذ الإجراءات على عدة طلبات معاً'}</p></div></div>{selectedIds.length > 0 && <div className="flex flex-wrap items-center gap-2"><select disabled={bulkBusy} defaultValue="" onChange={(event) => { const value = event.target.value as OrderStatus; if (value) void bulkUpdate(value); event.currentTarget.value = ''; }} className="rounded-xl bg-slate-950 px-3 py-2.5 text-xs font-black text-white outline-none"><option value="">تغيير الحالة</option><option value="complete">مكتملة</option><option value="confirmed">مؤكدة</option><option value="not_responding">لا يستجيب</option><option value="cancelled">ملغاة</option></select><button type="button" disabled={bulkBusy} onClick={() => void bulkUpdate(null, 'trash')} className="flex items-center gap-1.5 rounded-xl bg-rose-50 px-3 py-2.5 text-xs font-black text-rose-700 transition hover:bg-rose-100 disabled:opacity-50"><Trash2 className="h-4 w-4" /> نقل للسلة</button><button type="button" onClick={() => setSelectedIds([])} className="rounded-xl px-2.5 py-2.5 text-xs font-bold text-slate-500 hover:bg-slate-100">إلغاء</button></div>}</div>
          {error && <div className="mb-4 flex items-center justify-between rounded-2xl bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-700 ring-1 ring-rose-100"><span>{error}</span><button type="button" onClick={() => setError('')}><X className="h-4 w-4" /></button></div>}
          {loading && orders.length === 0 ? <div className="rounded-[24px] bg-white p-14 text-center text-slate-500 shadow-sm ring-1 ring-slate-200/70">جارٍ تحميل الطلبات...</div> : visibleOrders.length === 0 ? <div className="rounded-[24px] bg-white p-14 text-center text-slate-500 shadow-sm ring-1 ring-slate-200/70">لا توجد طلبات في هذا القسم.</div> : <div className="space-y-3">{visibleOrders.map((order) => <article key={order.id} className={`rounded-[24px] bg-white p-4 shadow-sm ring-1 transition hover:shadow-md sm:p-5 ${selectedIds.includes(order.id) ? 'ring-emerald-300 bg-emerald-50/20' : 'ring-slate-200/70'}`}><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 flex-1 items-start gap-3"><button type="button" onClick={(event) => { event.stopPropagation(); toggleSelected(order.id); }} className={`mt-1 flex h-6 w-6 shrink-0 items-center justify-center rounded-lg border transition ${selectedIds.includes(order.id) ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300 bg-white text-transparent hover:border-emerald-400'}`} aria-label={selectedIds.includes(order.id) ? 'إلغاء تحديد الطلب' : 'تحديد الطلب'}>{selectedIds.includes(order.id) && <Check className="h-4 w-4" />}</button><button type="button" onClick={() => openOrder(order)} className="min-w-0 flex-1 text-right"><div className="flex items-center gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-emerald-50 text-lg font-black text-emerald-700">{(order.full_name || 'ز').slice(0, 1)}</div><div className="min-w-0"><p className="truncate font-black text-slate-950">{order.full_name || 'زبون بدون اسم'}</p><p className="mt-1 text-xs font-bold text-slate-400">{order.lead_id} · {formatDate(order.updated_at)}</p></div></div></button></div><button type="button" onClick={() => openOrder(order)} className="flex h-10 items-center gap-1 rounded-xl border border-slate-200 bg-white px-2.5 text-slate-500 shadow-sm transition hover:border-emerald-300 hover:bg-emerald-50 hover:text-emerald-700" aria-label="فتح تفاصيل الطلب"><span className="text-[10px] font-black">تفاصيل</span><ChevronDown className="h-4 w-4" /></button></div><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto_auto] sm:items-center"><div className="flex min-w-0 items-center gap-2 text-sm text-slate-500"><Phone className="h-4 w-4 shrink-0 text-emerald-500" /><a href={`tel:${order.phone}`} onClick={(event) => event.stopPropagation()} className="font-bold text-slate-700 underline decoration-slate-200 underline-offset-4">{order.phone}</a><span className="text-slate-300">·</span><span className="truncate">{order.wilaya || '—'}{order.commune ? `، ${order.commune}` : ''}</span></div><div className="flex flex-wrap items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ring-1 ${statusTone(order.status)}`}>{statusLabels[order.status]}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ring-1 ${ecoTone(order)}`}>{ecoStatusLabel(order.ecotrack_status)}</span></div><div className="text-left"><p className="text-lg font-black text-slate-950">{order.price + (order.delivery_fee || 0)} <span className="text-xs font-bold text-slate-400">دج</span></p><p className="text-[11px] font-semibold text-slate-400">{order.ecotrack_tracking || 'بدون رقم تتبع'}</p></div></div><div className="mt-4 border-t border-slate-100 pt-3"><div className="mb-2 flex items-center justify-between"><p className="text-xs font-semibold text-slate-400">{order.shipping_provider_name || 'شركة التوصيل غير محددة'}</p><span className="text-[10px] font-bold text-slate-400">إجراءات الطلب</span></div><div className="grid grid-cols-3 gap-2"><select value={order.status} onChange={(event) => void updateStatus(order.id, event.target.value as OrderStatus)} disabled={loading || ['shipped', 'delivered', 'returned', 'trashed'].includes(order.status)} aria-label="حالة الطلبية" className="min-w-0 rounded-xl border border-slate-200 bg-slate-50 px-2 py-2.5 text-center text-[11px] font-black text-slate-700 outline-none transition hover:border-emerald-300 focus:border-emerald-400 focus:ring-2 focus:ring-emerald-400/20 disabled:cursor-not-allowed disabled:opacity-60"><option value="abandoned">غير مكتملة</option><option value="complete">مكتملة</option><option value="confirmed">مؤكدة</option><option value="not_responding">لا يستجيب</option><option value="cancelled">ملغاة</option><option value="shipped">مرفوعة</option><option value="delivered">تم التسليم</option><option value="returned">مرتجعة</option><option value="trashed">في السلة</option></select><button type="button" onClick={() => { openOrder(order); startEditing(order); }} className="flex min-w-0 items-center justify-center gap-1 rounded-xl bg-blue-50 px-2 py-2.5 text-[11px] font-black text-blue-700 transition hover:bg-blue-100"><Pencil className="h-3.5 w-3.5 shrink-0" /><span className="truncate">تعديل الطلب</span></button><button type="button" onClick={() => openOrder(order)} className="flex min-w-0 items-center justify-center gap-1 rounded-xl bg-emerald-50 px-2 py-2.5 text-[11px] font-black text-emerald-700 transition hover:bg-emerald-100"><Truck className="h-3.5 w-3.5 shrink-0" /><span className="truncate">حالة EcoTrack</span></button></div></div>{expandedId === order.id && <div className="mt-4 rounded-2xl bg-slate-50 p-4 text-sm"><div className="grid gap-3 sm:grid-cols-3"><div><p className="text-[11px] font-bold text-slate-400">العنوان</p><p className="mt-1 font-bold">{order.wilaya || '—'}{order.commune ? `، ${order.commune}` : ''}</p></div><div><p className="text-[11px] font-bold text-slate-400">المبلغ</p><p className="mt-1 font-bold">{order.price} + {order.delivery_fee || 0} دج</p></div><div><p className="text-[11px] font-bold text-slate-400">آخر تحديث</p><p className="mt-1 font-bold">{formatDate(order.updated_at)}</p></div></div><div className="mt-4 flex flex-wrap gap-2">{order.status === 'confirmed' && !order.ecotrack_tracking && <button type="button" onClick={() => void runAction(order.id, 'ship')} className="flex items-center gap-2 rounded-xl bg-emerald-500 px-4 py-2.5 text-xs font-black text-white"><Truck className="h-4 w-4" /> شحن الطلب</button>}{order.ecotrack_tracking && !['delivered', 'returned'].includes(order.status) && <button type="button" onClick={() => void runAction(order.id, 'unship')} className="flex items-center gap-2 rounded-xl bg-orange-50 px-4 py-2.5 text-xs font-black text-orange-700"><X className="h-4 w-4" /> إلغاء الرفع</button>}{!['shipped', 'delivered', 'returned', 'cancelled', 'trashed'].includes(order.status) && <button type="button" onClick={() => startEditing(order)} className="flex items-center gap-2 rounded-xl bg-blue-50 px-4 py-2.5 text-xs font-black text-blue-700"><Pencil className="h-4 w-4" /> تعديل</button>}{order.status === 'trashed' ? <button type="button" onClick={() => void runAction(order.id, 'restore')} className="rounded-xl bg-emerald-50 px-4 py-2.5 text-xs font-black text-emerald-700">استرجاع</button> : <button type="button" onClick={() => void runAction(order.id, 'trash')} className="rounded-xl bg-slate-200 px-4 py-2.5 text-xs font-black text-slate-700">نقل للسلة</button>}</div></div>}</article>)}</div>}
        </section>
      </div>
      {drawerOpen && <div className="fixed inset-0 z-40 bg-slate-950/30 backdrop-blur-[2px]" onClick={() => setDrawerOpen(false)} />}
      <aside className={`fixed inset-y-0 right-0 z-50 w-[min(92vw,390px)] overflow-y-auto bg-white p-5 shadow-2xl transition-transform duration-200 ${drawerOpen ? 'translate-x-0' : 'translate-x-full'}`}><div className="mb-6 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-emerald-600">ATLASIO</p><h2 className="mt-1 text-xl font-black">الأدوات</h2></div><button type="button" onClick={() => setDrawerOpen(false)} className="flex h-10 w-10 items-center justify-center rounded-2xl bg-slate-100"><X className="h-5 w-5" /></button></div><div className="mb-5 space-y-2 border-b border-slate-100 pb-5"><p className="px-1 text-xs font-black text-slate-400">الأقسام</p><button type="button" onClick={() => goToSection('orders')} className={`flex w-full items-center justify-between rounded-2xl p-4 text-right text-sm font-black ${section === 'orders' ? 'bg-slate-950 text-white' : 'bg-slate-50 text-slate-700'}`}><span className="flex items-center gap-3"><ClipboardList className="h-5 w-5" /> الطلبات</span><span>{(counts.confirmed || 0) + (counts.cancelled || 0) + (counts.shipped || 0)}</span></button><button type="button" onClick={() => goToSection('incomplete')} className={`flex w-full items-center justify-between rounded-2xl p-4 text-right text-sm font-black ${section === 'incomplete' ? 'bg-amber-50 text-amber-800' : 'bg-slate-50 text-slate-700'}`}><span className="flex items-center gap-3"><Package className="h-5 w-5" /> غير مكتملة</span><span>{(counts.abandoned || 0) + (counts.not_responding || 0)}</span></button><button type="button" onClick={() => goToSection('trash')} className={`flex w-full items-center justify-between rounded-2xl p-4 text-right text-sm font-black ${section === 'trash' ? 'bg-rose-50 text-rose-800' : 'bg-slate-50 text-slate-700'}`}><span className="flex items-center gap-3"><Archive className="h-5 w-5" /> سلة المهملات</span><span>{counts.trashed || 0}</span></button></div><div className="space-y-3"><button type="button" onClick={() => { void syncStatuses(); setDrawerOpen(false); }} className="flex w-full items-center justify-between rounded-2xl bg-blue-50 p-4 text-right text-sm font-black text-blue-700"><span className="flex items-center gap-3"><RefreshCw className={`h-5 w-5 ${syncing ? 'animate-spin' : ''}`} /> مزامنة حالات EcoTrack</span><span className="text-xs text-blue-400">الآن</span></button><button type="button" onClick={() => void shipAll()} disabled={loading} className="flex w-full items-center justify-between rounded-2xl bg-emerald-500 p-4 text-right text-sm font-black text-white disabled:opacity-60"><span className="flex items-center gap-3"><Truck className="h-5 w-5" /> شحن الطلبات المؤكدة</span><span>{confirmedCount}</span></button></div><button type="button" onClick={() => { setSettingsOpen(true); setDrawerOpen(false); }} className="mt-6 flex w-full items-center justify-between rounded-2xl bg-slate-950 p-4 text-right text-sm font-black text-white shadow-lg shadow-slate-950/10 transition hover:bg-emerald-700"><span className="flex items-center gap-3"><Settings className="h-5 w-5" /> إعدادات شركات الشحن</span><ChevronDown className="h-4 w-4 rotate-90" /></button></aside>
      {settingsOpen && <div className="fixed inset-0 z-[60] flex items-end justify-center bg-slate-950/45 p-0 backdrop-blur-sm sm:items-center sm:p-6" onClick={() => setSettingsOpen(false)}><section className="max-h-[94vh] w-full max-w-5xl overflow-y-auto rounded-t-[30px] bg-[#f7faf8] p-5 shadow-2xl sm:rounded-[30px] sm:p-7" onClick={(event) => event.stopPropagation()}><div className="mb-6 flex items-start justify-between"><div><p className="text-xs font-black uppercase tracking-[.2em] text-emerald-600">ATLASIO / SHIPPING</p><h2 className="mt-1 text-2xl font-black text-slate-950">شركات التوصيل</h2><p className="mt-1 text-sm text-slate-500">اختر شركة لعرض بياناتها وتعديل التوكن ومراجعة مخزونها.</p></div><button type="button" onClick={() => setSettingsOpen(false)} className="flex h-11 w-11 items-center justify-center rounded-2xl bg-white text-slate-500 shadow-sm ring-1 ring-slate-200"><X className="h-5 w-5" /></button></div>{error && <div className="mb-4 flex items-center justify-between rounded-2xl bg-rose-50 px-4 py-3 text-sm font-bold text-rose-700 ring-1 ring-rose-100"><span>{error}</span><button type="button" onClick={() => setError('')}><X className="h-4 w-4" /></button></div>}<div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div><div className="mb-3 flex items-center justify-between"><h3 className="font-black text-slate-900">الشركات المرتبطة</h3><button type="button" onClick={startNewProvider} className="rounded-xl bg-emerald-500 px-3 py-2 text-xs font-black text-white">+ شركة جديدة</button></div>{providers.length === 0 ? <div className="rounded-2xl bg-white p-8 text-center text-sm font-bold text-slate-500 ring-1 ring-slate-200">لا توجد شركة توصيل بعد.</div> : <div className="grid gap-3 sm:grid-cols-2">{providers.map((item) => <button type="button" key={item.id} onClick={() => selectProviderForEdit(item)} className={`min-h-[108px] rounded-2xl p-4 text-right transition ${editingProviderId === item.id ? 'bg-slate-950 text-white shadow-lg' : 'bg-white text-slate-800 shadow-sm ring-1 ring-slate-200 hover:-translate-y-0.5 hover:ring-emerald-300'}`}><div className="flex items-center justify-between"><span className="text-base font-black">{item.name}</span><span className={`rounded-full px-2 py-1 text-[10px] font-black ${editingProviderId === item.id ? 'bg-white/15 text-emerald-200' : item.tokenConfigured ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'}`}>{item.tokenConfigured ? 'متصل' : 'يحتاج توكن'}</span></div></button>)}</div>}</div><div className="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200">{editingProviderId ? <><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold text-emerald-600">تفاصيل الشركة</p><h3 className="mt-1 text-lg font-black">{providerNameDraft || 'شركة التوصيل'}</h3></div><button type="button" onClick={() => void refreshStock(selectedProviderId || activeProviderId)} className="flex items-center gap-1 rounded-xl bg-slate-100 px-3 py-2 text-xs font-black text-slate-600"><RefreshCw className="h-3.5 w-3.5" /> تحديث المخزون</button></div><div className="mb-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-emerald-50 p-4"><p className="text-xs font-bold text-emerald-700">المنتجات المتاحة</p><p className="mt-2 text-2xl font-black text-emerald-900">{stockProducts.length}</p></div><div className="rounded-2xl bg-blue-50 p-4"><p className="text-xs font-bold text-blue-700">إجمالي الكمية</p><p className="mt-2 text-2xl font-black text-blue-900">{stockProducts.reduce((sum, item) => sum + item.quantity, 0)}</p></div></div><div className="space-y-3"><label className="block text-xs font-black text-slate-500">اسم الشركة<input value={providerNameDraft} onChange={(event) => setProviderNameDraft(event.target.value)} className="mt-1.5 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm font-bold outline-none focus:border-emerald-400 focus:bg-white" /></label><label className="block text-xs font-black text-slate-500">Provider<input value={provider} onChange={(event) => setProvider(event.target.value)} dir="ltr" className="mt-1.5 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-left text-sm font-bold outline-none focus:border-emerald-400 focus:bg-white" /></label><label className="block text-xs font-black text-slate-500">التوكن<input type="password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="اتركه فارغاً للإبقاء على التوكن الحالي" dir="ltr" className="mt-1.5 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-left text-sm font-bold outline-none focus:border-emerald-400 focus:bg-white" /></label><button type="button" onClick={() => void saveProviderProfile()} disabled={savingSettings} className="flex w-full items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 py-3.5 text-sm font-black text-white disabled:opacity-60">{savingSettings && <Loader2 className="h-4 w-4 animate-spin" />} حفظ بيانات الشركة</button></div><div className="mt-5 rounded-2xl bg-amber-50 p-4"><p className="text-xs font-black text-amber-800">طريقة الشحن</p><div className="mt-3 grid grid-cols-2 gap-2"><button type="button" onClick={() => setShipFromStock(true)} className={`rounded-xl px-3 py-2.5 text-xs font-black ${shipFromStock ? 'bg-emerald-500 text-white' : 'bg-white text-slate-500'}`}>من stock</button><button type="button" onClick={() => setShipFromStock(false)} className={`rounded-xl px-3 py-2.5 text-xs font-black ${!shipFromStock ? 'bg-blue-500 text-white' : 'bg-white text-slate-500'}`}>بدون stock</button></div><select value={selectedStockProductId} onChange={(event) => setSelectedStockProductId(event.target.value)} disabled={!shipFromStock || stockProducts.length === 0} className="mt-3 w-full rounded-xl bg-white px-3 py-3 text-xs font-bold disabled:opacity-60"><option value="">{stockProducts.length ? 'منتج اختياري — stock مباشر' : 'الشركة لا توفر كتالوج منتجات؛ stock مباشر'}</option>{stockProducts.map((item) => <option key={item.id} value={item.id}>{item.name} · المتاح {item.quantity}</option>)}</select></div></> : <div className="flex min-h-[360px] flex-col items-center justify-center rounded-2xl bg-slate-50 p-8 text-center"><Settings className="h-10 w-10 text-slate-300" /><h3 className="mt-4 font-black text-slate-700">اختر شركة توصيل</h3><p className="mt-2 max-w-xs text-sm leading-6 text-slate-500">اضغط على إحدى البطاقات لعرض التوكن، تفاصيل الاتصال، ومعلومات المخزون.</p></div>}</div></div></section></div>}{activeOrder && <div className="fixed inset-0 z-30 flex items-end justify-center bg-slate-950/35 p-0 backdrop-blur-[2px] sm:p-6" onClick={closeOrder}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-[28px] bg-white p-5 shadow-2xl sm:rounded-[28px]" onClick={(event) => event.stopPropagation()}><div className="mb-5 flex items-start justify-between"><div><p className="text-xs font-bold text-emerald-600">{activeOrder.lead_id}</p><h2 className="mt-1 text-xl font-black">تفاصيل الطلب</h2></div><button type="button" onClick={closeOrder} className="flex h-10 w-10 items-center justify-center rounded-2xl bg-slate-100"><X className="h-5 w-5" /></button></div><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold text-slate-400">العميل</p><p className="mt-1 font-black">{activeOrder.full_name || 'زبون بدون اسم'}</p><a href={`tel:${activeOrder.phone}`} className="mt-1 block text-sm font-bold text-emerald-700 underline">{activeOrder.phone}</a></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold text-slate-400">الموقع</p><p className="mt-1 font-black">{activeOrder.wilaya || '—'}</p><p className="text-sm text-slate-500">{activeOrder.commune || '—'}</p></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold text-slate-400">حالة الطلب</p><span className={`mt-2 inline-flex rounded-full px-3 py-1.5 text-xs font-black ring-1 ${statusTone(activeOrder.status)}`}>{statusLabels[activeOrder.status]}</span></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold text-slate-400">حالة الشحن</p><span className={`mt-2 inline-flex rounded-full px-3 py-1.5 text-xs font-black ring-1 ${ecoTone(activeOrder)}`}>{ecoStatusLabel(activeOrder.ecotrack_status)}</span><p className="mt-2 break-all text-xs font-bold text-slate-500">{activeOrder.ecotrack_tracking || 'لا يوجد رقم تتبع'}</p></div></div><div className="mt-4 flex items-center justify-between rounded-2xl bg-emerald-50 p-4"><div><p className="text-xs font-bold text-emerald-700">الإجمالي</p><p className="mt-1 text-2xl font-black text-emerald-900">{activeOrder.price + (activeOrder.delivery_fee || 0)} <span className="text-sm">دج</span></p></div><p className="text-xs font-bold text-emerald-700">{activeOrder.shipping_provider_name || 'شركة التوصيل غير محددة'}</p></div><div className="mt-5 flex flex-wrap gap-2">{activeOrder.status === 'confirmed' && !activeOrder.ecotrack_tracking && <><button type="button" onClick={() => void runAction(activeOrder.id, 'ship', 'stock')} className="flex items-center gap-2 rounded-2xl bg-emerald-500 px-4 py-3 text-sm font-black text-white"><Truck className="h-4 w-4" /> شحن من stock</button><button type="button" onClick={() => void runAction(activeOrder.id, 'ship', 'without_stock')} className="flex items-center gap-2 rounded-2xl bg-blue-50 px-4 py-3 text-sm font-black text-blue-700"><Package className="h-4 w-4" /> بدون stock</button></>}{activeOrder.ecotrack_tracking && !['delivered', 'returned'].includes(activeOrder.status) && <button type="button" onClick={() => void runAction(activeOrder.id, 'unship')} className="flex items-center gap-2 rounded-2xl bg-orange-50 px-4 py-3 text-sm font-black text-orange-700"><X className="h-4 w-4" /> إلغاء الرفع</button>}{!['shipped', 'delivered', 'returned', 'cancelled', 'trashed'].includes(activeOrder.status) && <button type="button" onClick={() => startEditing(activeOrder)} className="flex items-center gap-2 rounded-2xl bg-blue-50 px-4 py-3 text-sm font-black text-blue-700"><Pencil className="h-4 w-4" /> تعديل الطلب</button>}{activeOrder.status === 'trashed' ? <button type="button" onClick={() => void runAction(activeOrder.id, 'restore')} className="rounded-2xl bg-emerald-50 px-4 py-3 text-sm font-black text-emerald-700">استرجاع</button> : <button type="button" onClick={() => void runAction(activeOrder.id, 'trash')} className="rounded-2xl bg-slate-100 px-4 py-3 text-sm font-black text-slate-700">نقل للسلة</button>}</div>{editing?.id === activeOrder.id && <form onSubmit={saveEdit} className="mt-5 space-y-3 rounded-2xl border border-blue-100 bg-blue-50/40 p-4"><input value={editForm.fullName} onChange={(event) => setEditForm({ ...editForm, fullName: event.target.value })} placeholder="الاسم (اختياري)" className="w-full rounded-xl bg-white px-3 py-3 text-right" /><div className="grid grid-cols-2 gap-2"><input required type="number" min="0" value={editForm.price} onChange={(event) => setEditForm({ ...editForm, price: event.target.value })} placeholder="سعر المنتج" className="w-full rounded-xl bg-white px-3 py-3 text-left" dir="ltr" /><input required type="number" min="0" value={editForm.deliveryFee} onChange={(event) => setEditForm({ ...editForm, deliveryFee: event.target.value })} placeholder="سعر التوصيل" className="w-full rounded-xl bg-white px-3 py-3 text-left" dir="ltr" /></div><input required value={editForm.phone} onChange={(event) => setEditForm({ ...editForm, phone: event.target.value })} placeholder="الهاتف" className="w-full rounded-xl bg-white px-3 py-3 text-left" dir="ltr" /><select required value={editForm.wilaya} onChange={(event) => { setEditForm({ ...editForm, wilaya: event.target.value, commune: '' }); setEditCommunes([]); void fetch(`/api/orders?resource=communes&wilaya=${encodeURIComponent(event.target.value)}`).then((response) => response.ok ? response.json() : Promise.reject(new Error('communes'))).then((data: { communes?: Array<{ name: string; hasStopDesk: boolean }> }) => setEditCommunes(data.communes || [])).catch(() => setEditCommunes([])); }} className="w-full rounded-xl bg-white px-3 py-3 text-right"><option value="">اختر الولاية</option>{WILAYAS.map((item) => <option key={item} value={item}>{item}</option>)}</select><select required value={editForm.commune} onChange={(event) => setEditForm({ ...editForm, commune: event.target.value })} disabled={!editForm.wilaya || editCommunes.length === 0} className="w-full rounded-xl bg-white px-3 py-3 text-right"><option value="">{editCommunes.length ? 'اختر البلدية' : 'جاري تحميل البلديات...'}</option>{editCommunes.map((item) => <option key={item.name} value={item.name}>{item.name}</option>)}</select><div className="flex gap-2"><button type="submit" className="flex-1 rounded-xl bg-slate-950 px-3 py-3 text-sm font-black text-white">حفظ التعديل</button><button type="button" onClick={() => setEditing(null)} className="flex-1 rounded-xl bg-white px-3 py-3 text-sm font-bold text-slate-600 ring-1 ring-slate-200">إلغاء</button></div></form>}</div></div>}
    </main>
  );
}
